// constat:template id=jest-mutation version=52 sha256=78e9d8ddd13d0774a6f9161339d27680127ecca12d98bbb9c89da5a9a6326d8b
// Generated by DoneMark's onboarding pull request. Produces the "constat-check-report-mutation"
// workflow artifact: does a check that runs a line this change added or altered actually NOTICE
// that line being wrong? Only ever mutates lines this change's own diff introduced — nothing
// outside it is ever touched, however long the run goes — and every mutant's edit is reverted,
// in a finally, before the next one is even planned.
//
// Usage: node .github/scripts/constat-jest-mutation.mjs <base-ref> <outputFile>
//   env MUTATION_MAX_MUTANTS    (default 6)   — the mutant-count cap.
//   env MUTATION_BUDGET_SECONDS (default 240) — the wall-clock cap for the whole mutation loop.

import { execFileSync } from 'node:child_process';
import { existsSync, mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { dirname, join, relative, resolve } from 'node:path';

const [, , baseRef, outputFile] = process.argv;
if (!baseRef || !outputFile) {
  console.error('usage: constat-jest-mutation.mjs <base-ref> <outputFile>');
  process.exit(2);
}

const repoRoot = process.cwd();
const MAX_MUTANTS = Number(process.env.MUTATION_MAX_MUTANTS ?? 6);
const BUDGET_MS = Number(process.env.MUTATION_BUDGET_SECONDS ?? 240) * 1000;
const TEST_FILE_RE = /\.(test|spec)\.[cm]?[jt]sx?$/;
const SOURCE_FILE_RE = /\.[cm]?[jt]sx?$/;

// ---- 1. Which lines did this change add or alter? Git's own diff, never a wider scan. ----

execFileSync('git', ['fetch', '--no-tags', 'origin', baseRef], { stdio: 'inherit' });
const mergeBase = execFileSync('git', ['merge-base', 'FETCH_HEAD', 'HEAD'], { encoding: 'utf8' }).trim();
const nameStatus = execFileSync(
  'git', ['diff', '--name-status', '--diff-filter=ACMR', mergeBase, 'HEAD'], { encoding: 'utf8' },
);
const changedFiles = nameStatus.split('\n').map((l) => l.trim()).filter(Boolean).map((l) => l.split('\t').pop());

const HUNK_HEADER = /^@@ -\d+(?:,\d+)? \+(\d+)(?:,\d+)? @@/;
function addedLines(patch) {
  const lines = [];
  let newLine = 0;
  let inHunk = false;
  for (const raw of patch.split('\n')) {
    const header = HUNK_HEADER.exec(raw);
    if (header) { newLine = Number(header[1]); inHunk = true; continue; }
    if (!inHunk) continue;
    if (raw.startsWith('+') && !raw.startsWith('+++')) { lines.push(newLine); newLine += 1; }
    else if (raw.startsWith('-') && !raw.startsWith('---')) { /* not in the new file */ }
    else if (raw.startsWith('\\')) { /* no-newline marker */ }
    else { newLine += 1; }
  }
  return lines;
}

const changedLines = new Map(); // file -> Set<line>
for (const file of changedFiles) {
  if (!file || !SOURCE_FILE_RE.test(file) || TEST_FILE_RE.test(file)) continue;
  if (!existsSync(join(repoRoot, file))) continue; // deleted — nothing to mutate
  const patch = execFileSync('git', ['diff', '--unified=0', mergeBase, 'HEAD', '--', file], { encoding: 'utf8' });
  const added = addedLines(patch);
  if (added.length > 0) changedLines.set(file, new Set(added));
}

// ---- 2. Which of those lines does this script know how to break? ----

const OPERATORS = [
  ['===', '!=='], ['!==', '==='], ['>=', '<'], ['<=', '>'], ['==', '!='], ['!=', '=='], ['&&', '||'], ['||', '&&'],
];
function isCommentOnly(line) {
  const t = line.trim();
  return t === '' || t.startsWith('//') || t.startsWith('*') || t.startsWith('/*');
}
function describeMutation(line) {
  if (isCommentOnly(line)) return null;
  for (const [from, to] of OPERATORS) {
    if (line.includes(from)) {
      const mutated = line.replace(from, to);
      if (mutated !== line) return { description: `inverted the operator: '${from}' became '${to}'`, mutated };
    }
  }
  if (/return\s+(true|false)\s*;\s*$/.test(line)) {
    const mutated = line.replace(/return\s+(true|false)(\s*;\s*)$/, (_m, b, tail) => `return ${b === 'true' ? 'false' : 'true'}${tail}`);
    if (mutated !== line) return { description: 'flipped a fixed boolean return value', mutated };
  }
  if (/^\s*(if|while)\s*\(.+\)\s*\{?\s*$/.test(line) && !/^\s*(if|while)\s*\(\s*!/.test(line)) {
    const mutated = line.replace(
      /^(\s*)(if|while)(\s*)\((.+)\)(\s*\{?\s*)$/,
      (_m, indent, kw, sp, cond, tail) => `${indent}${kw}${sp}(!(${cond}))${tail}`,
    );
    if (mutated !== line) return { description: 'negated the whole condition', mutated };
  }
  return null;
}

const candidates = [];
for (const file of [...changedLines.keys()].sort()) {
  const text = readFileSync(join(repoRoot, file), 'utf8');
  const lines = text.split('\n');
  for (const line of [...changedLines.get(file)].sort((a, b) => a - b)) {
    const described = describeMutation(lines[line - 1] ?? '');
    if (described) candidates.push({ file, line, ...described });
  }
}
const planned = candidates.slice(0, MAX_MUTANTS);
if (candidates.length > planned.length) {
  console.warn(
    `::warning::${candidates.length} mutable line(s) found in this change, capped at ${MAX_MUTANTS} — ` +
      `${candidates.length - planned.length} will not be attempted this run.`,
  );
}
if (planned.length === 0) {
  mkdirSync(dirname(outputFile), { recursive: true });
  writeFileSync(outputFile, `${JSON.stringify({
    schema: 'constat.check-mutation/v1', plannedMutants: 0, attemptedMutants: 0, stoppedEarly: false,
    budgetSeconds: BUDGET_MS / 1000, mutants: [],
  }, null, 2)}\n`);
  console.log(`no mutable line found in this change's diff against ${baseRef} — wrote an empty report`);
  process.exit(0);
}

// ---- 3. Run each mutant, in order, until the budget stops the loop. Revert, always. ----

const STATUS = { passed: 'passed', failed: 'failed', pending: 'skipped', skipped: 'skipped', todo: 'skipped' };
function readChecks(reportPath) {
  if (!existsSync(reportPath)) return [];
  const body = JSON.parse(readFileSync(reportPath, 'utf8'));
  const checks = [];
  for (const suite of body.testResults ?? []) {
    // Same relativization constat-jest-report.mjs's own translator applies to this same field —
    // jest's `--json` reporter names `suite.name` as an absolute path, and writing it through
    // unrelativized is exactly what leaves a report DoneMark can only match by the CI runner's own
    // disk path instead of the repo-relative one every other report here already uses.
    const file = typeof suite.name === 'string' ? relative(repoRoot, resolve(suite.name)) : null;
    for (const assertion of suite.assertionResults ?? []) {
      const status = STATUS[assertion.status];
      if (!status || typeof assertion.title !== 'string') continue;
      const ancestors = Array.isArray(assertion.ancestorTitles) ? assertion.ancestorTitles : [];
      checks.push({ name: [...ancestors, assertion.title].join(' > '), status, file });
    }
  }
  return checks;
}

const start = Date.now();
const mutants = [];
let stoppedEarly = false;

for (const mutant of planned) {
  if (Date.now() - start >= BUDGET_MS) { stoppedEarly = true; break; }

  const absPath = join(repoRoot, mutant.file);
  const original = readFileSync(absPath, 'utf8');
  const lines = original.split('\n');
  lines[mutant.line - 1] = mutant.mutated;
  let checks = [];
  try {
    writeFileSync(absPath, lines.join('\n'));
    const outDir = mkdtempSync(join(tmpdir(), 'constat-mut-'));
    const reportPath = join(outDir, 'report.json');
    try {
      execFileSync(
        'npx', ['jest', '--json', `--outputFile=${reportPath}`],
        { cwd: repoRoot, stdio: ['ignore', 'ignore', 'pipe'], timeout: 120_000 },
      );
    } catch {
      // A mutant is EXPECTED to make some check fail — jest exits non-zero for that, which is not
      // a script error. The report file (written even on a failing run) is still read below.
    }
    checks = readChecks(reportPath);
    rmSync(outDir, { recursive: true, force: true });
  } finally {
    // Restored before the NEXT mutant is even considered — never left broken across an error, a
    // timeout, or the budget stopping the loop right after this one.
    writeFileSync(absPath, original);
  }
  mutants.push({ file: mutant.file, line: mutant.line, description: mutant.description, checks });
}

const dirty = execFileSync('git', ['status', '--porcelain'], { encoding: 'utf8' }).trim();
if (dirty) {
  console.warn(`::warning::working tree not clean after the mutation run — restoring: ${dirty}`);
  execFileSync('git', ['checkout', '--', '.'], { stdio: 'inherit' });
}

mkdirSync(dirname(outputFile), { recursive: true });
writeFileSync(outputFile, `${JSON.stringify({
  schema: 'constat.check-mutation/v1',
  plannedMutants: planned.length,
  attemptedMutants: mutants.length,
  stoppedEarly,
  budgetSeconds: BUDGET_MS / 1000,
  mutants,
}, null, 2)}\n`);
console.log(
  `ran ${mutants.length} of ${planned.length} planned mutant(s)` +
    (stoppedEarly ? ' (stopped early at the time budget)' : '') + ` -> ${outputFile}`,
);
